// The variant draw and the input rules shared by the server and the app (src/classroomShared.ts) against the shared
// vectors (tools/variant_vectors.json, generated by the independent Python implementation in tools/variant_vectors.py).
// Run: npx tsx tools/variant_test.ts
import {readFileSync} from 'node:fs';
import {checkNick,drawVariant,maxVariantCount,normalizeCode,normalizeNick,sha256hex,variantAllowed} from '../src/classroomShared';

type Case={name:string;assignmentId:string;userId:string;pool:string[];count:number;primary:string|null;expected:number[]};
const v=JSON.parse(readFileSync(new URL('./variant_vectors.json',import.meta.url),'utf8')) as {sha256:{input:string;hex:string}[];cases:Case[]};
let n=0;
const check=(name:string,ok:boolean)=>{if(!ok){console.error('FAIL',name);process.exit(1)}n++};
const same=(a:unknown,b:unknown)=>JSON.stringify(a)===JSON.stringify(b);

for(const s of v.sha256)check(`sha256 ${JSON.stringify(s.input)}`,await sha256hex(s.input)===s.hex);
for(const c of v.cases){
 const got=await drawVariant(c.assignmentId,c.userId,c.pool,c.count,c.primary);
 if(!same(got,c.expected))console.error(c.name,'got',got,'expected',c.expected);
 check('vector: '+c.name,same(got,c.expected));
}
// Properties beyond the vectors: balance across topics and spread across students.
const pool=[...Array(3)].flatMap((_,t)=>[...Array(10)].map((_,i)=>`perio-0${t+1}:${i}`));
const sets=new Set<string>();
for(let u=0;u<12;u++){
 const got=await drawVariant('A-1','user-'+u,pool,9,'perio-01');
 const per=[1,2,3].map(t=>got.filter(i=>pool[i].startsWith(`perio-0${t}:`)).length);
 check('primary topic gets ceil(9/2)=5, the others 2 each',same(per,[5,2,2]));
 check('no repeats',new Set(got).size===9);
 sets.add([...got].sort((a,b)=>a-b).join(','));
}
check('students get different sets',sets.size>=10);
check('same student, same set',same(await drawVariant('A','u',pool,6,'perio-01'),await drawVariant('A','u',pool,6,'perio-01')));
check('variantAllowed needs 2×N',variantAllowed(10,5)&&!variantAllowed(10,6)&&!variantAllowed(10,0)&&maxVariantCount(10)===5&&maxVariantCount(25)===12);

// Nicknames: iPhone smart punctuation and Uzbek apostrophes become a plain '.
for(const raw of ['G’ayrat','G‘ayrat','Gʻayrat','Gʼayrat','G`ayrat','G´ayrat','G′ayrat',"G'ayrat",'  G’ayrat  '])check('apostrophe '+raw,normalizeNick(raw)==="G'ayrat"&&checkNick(raw).ok);
check('O‘tkir',same(checkNick('O‘tkir'),{ok:true,nick:"O'tkir"}));
check('spaces collapse',normalizeNick(' Lola   Karimova ')==='Lola Karimova');
for(const bad of ['a','a@b.uz','http://x.uz','😀Lola','-Lola','Lola!','x'.repeat(25)])check('bad nickname '+bad,!checkNick(bad).ok);
check('reserved numbered name',same(checkNick('Talaba 7'),{ok:false,error:'reserved_nickname'}));
for(const ok of ['Lola','Aziz 2','Мадина','Ra’no','Shoxruh.','Dr. Alimov'])check('good nickname '+ok,checkNick(ok).ok);

// Join codes: case, spaces, dashes and Cyrillic look-alikes are fine; 0/O/1/I are flagged.
check('code lower case and space',same(normalizeCode('g5r mba'),{code:'G5RMBA',ambiguous:false}));
check('code dash',normalizeCode('G5R-MBA').code==='G5RMBA');
check('Cyrillic look-alikes',normalizeCode('АВС КМР').code==='ABCKMP');
check('0 and O flagged',normalizeCode('G5R0BA').ambiguous&&normalizeCode('GORMBA').ambiguous);
check('1 and I flagged',normalizeCode('G5R1BA').ambiguous&&normalizeCode('GIRMBA').ambiguous);
console.log(`variant/nickname/code: ${n} checks passed`);
